                    <label>Full name<input value={adminForm.full_name} onChange={(event) => setAdminForm({ ...adminForm, full_name: event.target.value })} required /></label>
                    <label>Role<select value={adminForm.role} onChange={(event) => setAdminForm({ ...adminForm, role: event.target.value })}><option value="employee">Employee</option><option value="manager">Manager</option><option value="hr_admin">HR Admin</option></select></label>
                  </div>
                  <div className="leave-form-row">
                    <label>Email<input type="email" value={adminForm.email} onChange={(event) => setAdminForm({ ...adminForm, email: event.target.value })} required /></label>
                    <label>Phone<input value={adminForm.phone_number} onChange={(event) => setAdminForm({ ...adminForm, phone_number: event.target.value })} required /></label>
                  </div>
                  <div className="leave-form-row">
                    <label>Department<input value={adminForm.department} onChange={(event) => setAdminForm({ ...adminForm, department: event.target.value })} required /></label>
                    <label>Job title<input value={adminForm.job_position_title} onChange={(event) => setAdminForm({ ...adminForm, job_position_title: event.target.value })} /></label>
                  </div>
                  <div className="leave-form-row">
                    <label>Employer<input value={adminForm.employer} onChange={(event) => setAdminForm({ ...adminForm, employer: event.target.value })} /></label>
                    <label>Password<input type="password" value={adminForm.password} onChange={(event) => setAdminForm({ ...adminForm, password: event.target.value })} required /></label>
                  </div>
                  {isSuperAdmin && <label className="checkbox-row"><input type="checkbox" checked={Boolean(adminForm.is_superuser)} onChange={(event) => setAdminForm({ ...adminForm, is_superuser: event.target.checked })} /> Grant super-admin privileges</label>}
                  <div className="leave-modal-actions"><button type="submit" className="leave-primary-button">Create user</button></div>
                </form>
                <div className="admin-list-wrap">
                  <h4>All users</h4>
                  <div className="leave-table-wrap compact-table">
                    <table className="leave-table">
                      <thead><tr><th>Name</th><th>Role</th><th>Status</th><th>Department</th><th>Actions</th></tr></thead>
                      <tbody>
                        {adminUsers.length === 0 ? <tr><td colSpan="5">No users yet.</td></tr> : adminUsers.map((user) => (
                          <tr key={user.id}>
                            <td>{user.full_name}</td>
                            <td>
                              <select value={user.role} onChange={(event) => updateAdminUserRole(user.id, event.target.value, user.is_superuser)}>
                                <option value="employee">Employee</option>
                                <option value="manager">Manager</option>
                                <option value="hr_admin">HR Admin</option>
                              </select>
                              {isSuperAdmin && user.id !== currentUser.id && <label className="role-toggle"><input type="checkbox" checked={Boolean(user.is_superuser)} onChange={(event) => updateAdminUserRole(user.id, user.role, event.target.checked)} /> Super admin</label>}
                            </td>
                            <td><select value={user.state || (user.is_active ? 'active' : 'deactivated')} onChange={(event) => updateAdminUserStatus(user.id, event.target.value)} disabled={user.id === currentUser.id}><option value="active">Active</option><option value="deactivated">Deactivated</option><option value="archived">Archived</option></select></td>
                            <td>{user.department || user.department_details?.name || '—'}</td>
                            <td>
                              <button className="leave-text-button edit-action" type="button" onClick={() => startAdminUserEdit(user)}>Edit</button>
                              <button className="leave-text-button danger-action" type="button" onClick={() => deleteAdminUser(user.id)}>Delete</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
                {editingAdminUserId && <div className="leave-modal-backdrop employee-edit-backdrop" role="presentation"><div className="leave-modal employee-edit-modal" role="dialog" aria-modal="true" aria-labelledby="admin-user-edit-title"><div className="leave-modal-heading"><div><p className="leave-kicker">AUTHORITY</p><h2 id="admin-user-edit-title">Edit user profile</h2><p className="employee-edit-subtitle">Update {adminUsers.find((user) => user.id === editingAdminUserId)?.full_name || 'this user'}'s details and access.</p></div><button type="button" className="leave-close" onClick={() => setEditingAdminUserId(null)} aria-label="Close user editor">×</button></div><form onSubmit={saveAdminUser} className="admin-form admin-edit-form"><div className="employee-edit-section"><h3>Profile details</h3><div className="leave-form-row"><label>Full name<input value={adminUserForm.full_name} onChange={(event) => setAdminUserForm({ ...adminUserForm, full_name: event.target.value })} required /></label><label>Email<input type="email" value={adminUserForm.email} onChange={(event) => setAdminUserForm({ ...adminUserForm, email: event.target.value })} required /></label></div><div className="leave-form-row"><label>Phone<input value={adminUserForm.phone_number} onChange={(event) => setAdminUserForm({ ...adminUserForm, phone_number: event.target.value })} required /></label><label>Department<input value={adminUserForm.department} onChange={(event) => setAdminUserForm({ ...adminUserForm, department: event.target.value })} required /></label></div><div className="leave-form-row"><label>Job title<input value={adminUserForm.job_position_title} onChange={(event) => setAdminUserForm({ ...adminUserForm, job_position_title: event.target.value })} /></label><label>Employer<input value={adminUserForm.employer} onChange={(event) => setAdminUserForm({ ...adminUserForm, employer: event.target.value })} /></label></div></div>{isSuperAdmin && <div className="employee-edit-section"><h3>Access level</h3><label>Role<select value={adminUserForm.role} onChange={(event) => setAdminUserForm({ ...adminUserForm, role: event.target.value })}><option value="employee">Employee</option><option value="manager">Manager</option><option value="hr_admin">HR Admin</option></select></label><label className="checkbox-row"><input type="checkbox" checked={adminUserForm.is_superuser} onChange={(event) => setAdminUserForm({ ...adminUserForm, is_superuser: event.target.checked })} /> Super admin privileges</label><p className="employee-edit-note">Role changes affect dashboard access and approval permissions.</p></div>}<div className="leave-modal-actions"><button type="button" className="leave-secondary-button action-reset" onClick={() => setEditingAdminUserId(null)}>Cancel</button><button type="submit" className="leave-primary-button">Save changes</button></div></form></div></div>}
              </div>

              <div className="admin-card" id="departments">
                <h3>{editingDepartmentId ? 'Edit department' : 'Create department'}</h3>
                <form onSubmit={createDepartment} className="admin-form">
